-- Marca como INACTIVOS (active = FALSE) a los 98 estudiantes retirados
-- detectados en el plano oficial (ESTADO = RETIRADO).
-- Generado desde estudiantes.csv (columna active=false).
-- Pega esto en el SQL Editor de Supabase. Es idempotente: re-corrrerlo no cambia nada.

BEGIN;

UPDATE students SET active = FALSE WHERE document_id IN (
  '1039696494', '1019764575', 'N37667136664', '1074192766', 'N37666689808', 'N37666689816', '1023987573', 'N37666934392', 'N37665418491', 'N37664685154', '1028665811', 'N37686747592', '1044636494', '1023894888', '1011104588', '1047229854', '1206214715', '1033830945', '1073991524', '1206215050', '1051287445', '1021679644', '1070921996', '1021679468', 'N37666935351', 'N37666937959', '1124076643', '1028681508', '1025568655', '1016753283', '1144110506', '1144110505', 'N59924712622', '1028675589', '1021680302', '1020775187', '1022992570', '1110557370', '1110587312', '1024577571', '1023398621', '1016724336', '1010203907', '1073989777', '1010215204', '1043852831', '1083903469', '1022998773', '1022998169', '1028683805', 'N37666517220', '1110610461', 'N148947011925', 'N39724275902', '1016717316', '1028405937', '1022998659', '1025564081', '1025550972', '7835701', '1026278688', '1012921744', '1074813711', '1016752921', 'N37667142022', '1022953126', '1023046858', '1022965996', '1012475977', '7893462', 'CD573431', '7893465', '8156863', '1022999758', '1034660990', '1013621868', '1022963717', '1093924439', '1013700068', '1023984538', 'N37856939241', '1021683099', '7967241', '7967258', '1188966590', '1016599122', 'N37595437297', '1023987982', '1104841066', '1232792186', '1028944362', '1023989627', '1026564610', '90920227', '1023918671', '6094678', '5840188', '5840389'
);

COMMIT;

-- Verificacion: cuantos quedaron inactivos por curso
SELECT s.grade, count(*) FILTER (WHERE NOT s.active) AS inactivos,
       count(*) FILTER (WHERE s.active) AS activos, count(*) AS total
FROM students s
GROUP BY s.grade
ORDER BY s.grade;